"""Windows stand-in for the Unix-only `resource` module (native-Windows Frappe spike).
Frappe uses only getrusage(RUSAGE_SELF).ru_maxrss (prepared reports' peak memory); it is reported from the
process's real peak working set, in kilobytes as on Linux."""
from types import SimpleNamespace

RUSAGE_SELF = 0
RUSAGE_CHILDREN = -1


def getrusage(who=RUSAGE_SELF):
    import psutil
    info = psutil.Process().memory_info()
    return SimpleNamespace(ru_maxrss=getattr(info, "peak_wset", info.rss) // 1024)
